(*
dZPosition := 0.0;
FOR nCycle := 0 TO 5 BY 1 DO
  IF nCycle = 0 THEN
    dZPosition := dZPosition + dFactorsArray.dFactors[nCycle];
  ELSE
    dZPosition := dZPosition+ dFactorsArray.dFactors[nCycle] * EXPT(IN1 := dInputX,IN2 :=nCycle);
  END_IF;
END_FOR;  
FUN_ReturnZPosition := dZPosition;
*)

FUN_ReturnZPosition := dFactorsArray.dFactors[0] * EXPT(dInputX,0) + dFactorsArray.dFactors[1] * EXPT(dInputX,1)+ dFactorsArray.dFactors[2] * EXPT(dInputX,2) +dFactorsArray.dFactors[3] * EXPT(dInputX,3) + dFactorsArray.dFactors[4] * EXPT(dInputX,4) +dFactorsArray.dFactors[5] * EXPT(dInputX,5);
